#!/usr/bin/env node
/**
 * Compiles the comments UI's stylesheet (src/collab/cds/comments.css) with the Tailwind classes its views use
 * (src/collab/cds/*.tsx, CommentViews.tsx, CommentList.tsx) into src/collab/cds/comments-css.ts, the string
 * layer.tsx puts in each comments layer's shadow root.
 *
 * The output is committed, so building the editors needs no extra step; run this after changing comments.css or a
 * class in those views. `--check` only reports whether the committed file is current (exit code 1 when not).
 *
 *   node packages/editor-kit/scripts/build-comments-css.mjs [--check]
 */

import { compile, optimize } from '@tailwindcss/node';
import { Scanner } from '@tailwindcss/oxide';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const collab = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'collab');
const cds = join(collab, 'cds');
const OUT = join(cds, 'comments-css.ts');

/** The compiled, minified stylesheet. */
export async function buildCommentsCss() {
  const source = readFileSync(join(cds, 'comments.css'), 'utf8');
  const compiler = await compile(source, { base: cds, onDependency() {} });
  const candidates = new Scanner({
    sources: [
      { base: cds, pattern: '*.tsx', negated: false },
      { base: collab, pattern: 'Comment{Views,List}.tsx', negated: false },
    ],
  }).scan();
  return optimize(compiler.build(candidates), { minify: true }).code;
}

/** The module text of comments-css.ts for a stylesheet. */
export function commentsCssModule(css) {
  return [
    '// Generated by packages/editor-kit/scripts/build-comments-css.mjs from comments.css: do not edit.',
    '/** The comments UI stylesheet, put in each comments layer\'s shadow root (layer.tsx). */',
    `export const COMMENTS_CSS = ${JSON.stringify(css)};`,
    '',
  ].join('\n');
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const text = commentsCssModule(await buildCommentsCss());
  if (process.argv.includes('--check')) {
    const current = readFileSync(OUT, 'utf8') === text;
    console.log(current ? 'comments-css.ts is current' : 'comments-css.ts is out of date: run node packages/editor-kit/scripts/build-comments-css.mjs');
    process.exit(current ? 0 : 1);
  }
  writeFileSync(OUT, text);
  console.log(`wrote ${OUT} (${(text.length / 1024).toFixed(1)} KB)`);
}
